/* Maps a single-bit flag (0x10, 0x20, 0x40, 0x80) to its bit index (4-7), or 0 otherwise. */ s32 flagMaskToIndex(u32 mask) {

    switch (mask) {
    case 0x20:
        return 5;
    case 0x40:
        return 6;
    case 0x80:
        return 7;
    case 0x10:
        return 4;
    }
    return 0;
}
